#include <stdio.h>
#include <string.h>

// Define a structure for a Student
struct Student {
    int rollNo;
    char name[50];
    float marks;
};

// Function to display student details
void display(struct Student s) {
    printf("Roll No : %d\n", s.rollNo);
    printf("Name    : %s\n", s.name);
    printf("Marks   : %.2f\n", s.marks);
}

int main() {
    // Declare and initialize a structure variable
    struct Student s1;
    s1.rollNo = 101;
    strcpy(s1.name, "Priya");
    s1.marks = 92.5;

    printf("--- Student Details ---\n");
    display(s1);

    // Using a pointer to structure
    struct Student *ptr = &s1;
    printf("\nAccessing via pointer:\n");
    printf("Roll No : %d\n", ptr->rollNo);
    printf("Name    : %s\n", ptr->name);

    // Array of structures
    struct Student class[2];
    class[0].rollNo = 102;
    strcpy(class[0].name, "Amit");
    class[0].marks = 78.0;

    class[1].rollNo = 103;
    strcpy(class[1].name, "Sneha");
    class[1].marks = 88.5;

    printf("\n--- Class Records ---\n");
    for (int i = 0; i < 2; i++) {
        display(class[i]);
        printf("\n");
    }

    return 0;
}

